local SlackTubHoodMaker = {}
local PRODUCTS = {
    iron_slacktubhood = { name = "Železni pokrov za kalilne kadi", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni pokrov za kalilne kadi za kovace." },
    bronze_slacktubhood = { name = "Bronast pokrov za kalilne kadi", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast pokrov za kalilne kadi za kovace." },
    silver_slacktubhood = { name = "Srebrn pokrov za kalilne kadi", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn pokrov za kalilne kadi za kovace." },
    gilded_slacktubhood = { name = "Pozlačen pokrov za kalilne kadi", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen pokrov za kalilne kadi za kovace." },
    jewel_set_slacktubhood = { name = "Draguljast pokrov za kalilne kadi", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast pokrov za kalilne kadi za kovace." },
    royal_sovereign_slacktubhood = { name = "Kraljevski suveren pokrov za kalilne kadi", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren pokrov za kalilne kadi z biseri za krono." },
}
local BUILDINGS = {
    slacktubhood_workshop = { name = "Slacktubhood delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    slacktubhood_house = { name = "Slacktubhood hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_slacktubhood_atelier = { name = "Mojstrski slacktubhood atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_slacktubhood_palace = { name = "Suverena slacktubhood palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
SlackTubHoodMaker.ironStock=14; SlackTubHoodMaker.bronzeStock=12; SlackTubHoodMaker.woodStock=14; SlackTubHoodMaker.leatherStock=8; SlackTubHoodMaker.silverStock=8; SlackTubHoodMaker.goldStock=6; SlackTubHoodMaker.jewelStock=4; SlackTubHoodMaker.pearlStock=4
SlackTubHoodMaker.productStock = {}; SlackTubHoodMaker.buildings = {}; SlackTubHoodMaker.maker = nil; SlackTubHoodMaker.activeMaking = {}; SlackTubHoodMaker.totalProducts = 0; SlackTubHoodMaker.dayTimer = 0
function SlackTubHoodMaker.init() SlackTubHoodMaker.ironStock=14; SlackTubHoodMaker.bronzeStock=12; SlackTubHoodMaker.woodStock=14; SlackTubHoodMaker.leatherStock=8; SlackTubHoodMaker.silverStock=8; SlackTubHoodMaker.goldStock=6; SlackTubHoodMaker.jewelStock=4; SlackTubHoodMaker.pearlStock=4; SlackTubHoodMaker.productStock={}; SlackTubHoodMaker.buildings={}; SlackTubHoodMaker.maker=nil; SlackTubHoodMaker.activeMaking={}; SlackTubHoodMaker.totalProducts=0; SlackTubHoodMaker.dayTimer=0; print("[SlackTubHoodMaker] Royal Slack Tub Hood Maker System initialized (6 products, 4 buildings)") end
function SlackTubHoodMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SlackTubHoodMaker.maker={name=n or ("Pokrovnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pokrovnik najet: %s (spretnost: %d)",SlackTubHoodMaker.maker.name,s),"success") end; return true end
function SlackTubHoodMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SlackTubHoodMaker.build(id) local ok,e=SlackTubHoodMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SlackTubHoodMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SlackTubHoodMaker.getQualityBonus() local b=0; for _,bd in ipairs(SlackTubHoodMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SlackTubHoodMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and SlackTubHoodMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and SlackTubHoodMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and SlackTubHoodMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and SlackTubHoodMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and SlackTubHoodMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and SlackTubHoodMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SlackTubHoodMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and SlackTubHoodMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #SlackTubHoodMaker.buildings==0 then return false,"Potrebna pokrovna delavnica" end; if not SlackTubHoodMaker.maker then return false,"Potreben pokrovnik" end; return true end
function SlackTubHoodMaker.make(pt,qty) qty=qty or 1; local ok,e=SlackTubHoodMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then SlackTubHoodMaker.ironStock=SlackTubHoodMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then SlackTubHoodMaker.bronzeStock=SlackTubHoodMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then SlackTubHoodMaker.woodStock=SlackTubHoodMaker.woodStock-d.woodCost*qty end; if d.leatherCost then SlackTubHoodMaker.leatherStock=SlackTubHoodMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then SlackTubHoodMaker.silverStock=SlackTubHoodMaker.silverStock-d.silverCost*qty end; if d.goldCost then SlackTubHoodMaker.goldStock=SlackTubHoodMaker.goldStock-d.goldCost*qty end; if d.jewelCost then SlackTubHoodMaker.jewelStock=SlackTubHoodMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then SlackTubHoodMaker.pearlStock=SlackTubHoodMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if SlackTubHoodMaker.maker then t=math.max(1,t-math.floor(SlackTubHoodMaker.maker.skill/13)) end; table.insert(SlackTubHoodMaker.activeMaking,{id="slacktubhood_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SlackTubHoodMaker.completeMaking(m) local q=1.0+(SlackTubHoodMaker.getQualityBonus()/100); if SlackTubHoodMaker.maker then q=q+(SlackTubHoodMaker.maker.skill/140) end; q=math.min(2.5,q); SlackTubHoodMaker.productStock[m.productType]=(SlackTubHoodMaker.productStock[m.productType] or 0)+m.quantity; SlackTubHoodMaker.totalProducts=SlackTubHoodMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SlackTubHoodMaker.maker then SlackTubHoodMaker.maker.itemsMade=SlackTubHoodMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then SlackTubHoodMaker.maker.skill=math.min(100,SlackTubHoodMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pokrov izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"slacktubhood.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function SlackTubHoodMaker.update(dt) if not _G.state then return end; SlackTubHoodMaker.dayTimer=SlackTubHoodMaker.dayTimer+dt; if SlackTubHoodMaker.dayTimer>=30 then SlackTubHoodMaker.dayTimer=0; for i=#SlackTubHoodMaker.activeMaking,1,-1 do local m=SlackTubHoodMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SlackTubHoodMaker.completeMaking(m); table.remove(SlackTubHoodMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SlackTubHoodMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SlackTubHoodMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SlackTubHoodMaker.getStats() return {ironStock=SlackTubHoodMaker.ironStock,bronzeStock=SlackTubHoodMaker.bronzeStock,woodStock=SlackTubHoodMaker.woodStock,leatherStock=SlackTubHoodMaker.leatherStock,silverStock=SlackTubHoodMaker.silverStock,goldStock=SlackTubHoodMaker.goldStock,jewelStock=SlackTubHoodMaker.jewelStock,pearlStock=SlackTubHoodMaker.pearlStock,productStock=SlackTubHoodMaker.productStock,numBuildings=#SlackTubHoodMaker.buildings,hasMaker=SlackTubHoodMaker.maker~=nil,makerName=SlackTubHoodMaker.maker and SlackTubHoodMaker.maker.name or "—",makerSkill=SlackTubHoodMaker.maker and SlackTubHoodMaker.maker.skill or 0,activeMaking=#SlackTubHoodMaker.activeMaking,totalProducts=SlackTubHoodMaker.totalProducts} end
return SlackTubHoodMaker
